import json, re, os
from collections import Counter
manifest='/mnt/data/LSF/baseline_results/nopv/agentic_codex_qa_gpt54mini_all/benchmark_100/logs/benchmark_100.manifest.json'
with open(manifest) as f: data=json.load(f)
months='January February March April May June July August September October November December'.split()
month_re='(?:'+'|'.join(months)+')'
date_re=re.compile(month_re+r'\\s+\\d{1,2},\\s+\\d{4}')
states=[
'Alabama','Alaska','Arizona','Arkansas','California','Colorado','Connecticut','Delaware','Florida','Georgia','Hawaii','Idaho','Illinois','Indiana','Iowa','Kansas','Kentucky','Louisiana','Maine','Maryland','Massachusetts','Michigan','Minnesota','Mississippi','Missouri','Montana','Nebraska','Nevada','New Hampshire','New Jersey','New Mexico','New York','North Carolina','North Dakota','Ohio','Oklahoma','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming','District of Columbia']
state_re=re.compile(r'\\b('+'|'.join(map(re.escape,states))+r')\\b')
TITLE_KWS=['president','chief executive officer','ceo','vice president','chairman','director','manager','vice president and manager','vice president,','regional director','executive vice president','president & ceo','president and ceo','president and chief executive officer','general manager','operations manager']

def looks_address(line):
    return bool(re.search(r'\\b\\d{3,5}\\b', line) or re.search(r'\\b[A-Z]{2}\\s*\\d{5}(?:-\\d{4})?\\b', line) or re.search(r'\\bP\\.?O\\.? Box\\b', line, re.I) or re.search(r'\\bSuite\\b|\\bStreet\\b|\\bRoad\\b|\\bAve\\b|\\bAvenue\\b|\\bDrive\\b|\\bBlvd\\b|\\bLane\\b|\\bHighway\\b|\\bHwy\\b', line, re.I) and any(c.isdigit() for c in line))

def parse_date_and_cpf(text):
    m_cpf=re.search(r'\\bCPF\\s+(["'^'"\\n\\r]+)', text)
    cpf=m_cpf.group(1).strip() if m_cpf else None
    pre=text[:m_cpf.start()] if m_cpf else text
    m_date=date_re.search(pre)
    issue=m_date.group(0) if m_date else None
    block=pre[m_date.end():] if m_date else pre
    lines=[ln.strip() for ln in block.splitlines() if ln.strip()]
    lines=[ln for ln in lines if not ln.upper().startswith('VIA ELECTRONIC MAIL') and not ln.upper().startswith('OVERNIGHT EXPRESS DELIVERY')]
    addr_idx=None
    for i,ln in enumerate(lines):
        if looks_address(ln):
            addr_idx=i
            break
    preaddr=lines[:addr_idx] if addr_idx is not None else lines
    i=1
    while i < len(preaddr):
        l=preaddr[i].lower()
        if any(k in l for k in TITLE_KWS) or l.startswith(('mr.','ms.','mrs.','dr.')):
            i+=1
        else:
            break
    company_lines=[]
    for ln in preaddr[i:]:
        low=ln.lower()
        if low.startswith(('a subsidiary','an affiliate','a division','doing business as','d/b/a')):
            break
        if ln and ln[0].islower() and company_lines:
            break
        company_lines.append(ln)
    if not company_lines:
        for ln in reversed(preaddr):
            if not any(k in ln.lower() for k in TITLE_KWS) and not ln.lower().startswith(('mr.','ms.','mrs.','dr.')):
                company_lines=[ln]
                break
    return cpf, issue, ' '.join(company_lines).strip() if company_lines else None

def parse_opening(text):
    m_cpf=re.search(r'\\bCPF\\s+["'^'"\\n\\r]+', text)
    start=m_cpf.end() if m_cpf else 0
    m=re.search(r'\\bAs a result of the inspection\\b|\\bAs a result,?\\b', text[start:])
    end=start+m.start() if m else len(text)
    opening=text[start:end]
    m2=re.search(r'\\b(?:From|Between)\\s+(.+?)(?:,\\s*(?:representatives?|a representative|the Pipeline|PHMSA|a representative from|a representative of|and inspectors|and inspectors from)|\\n)', opening, re.S)
    if not m2:
        m2=re.search(r'\\bDuring\\s+(.+?)(?:,\\s*(?:representatives?|a representative|the Pipeline|PHMSA)|\\n)', opening, re.S)
    if not m2:
        m2=re.search(r'\\bOn\\s+(' + month_re + r'\\s+\\d{1,2},\\s+\\d{4})', opening)
    date_range=m2.group(1).strip().replace('\\n',' ') if m2 else None
    states_found=[]
    for s in state_re.findall(opening):
        if s not in states_found:
            states_found.append(s)
    return date_range, states_found, opening

def parse_signer(text):
    tail=text[text.rfind('Sincerely,'): ] if 'Sincerely,' in text else text[-2500:]
    m=re.search(r'\\n\\s*([A-Z][A-Za-z\\.,\\'\\- ]+?)\\n\\s*(Director,.*?Office of Pipeline Safety|Regional Director,.*?Office of Pipeline Safety|Director,.*?Pipeline and Hazardous Materials Safety Administration|Director,.*?Office of Pipeline Safety|Regional Director,.*?Pipeline and Hazardous Materials Safety Administration)', tail, re.S)
    if m:
        return m.group(1).strip(), m.group(2).strip()
    lines=[ln.strip() for ln in tail.splitlines() if ln.strip()]
    for i,ln in enumerate(lines):
        if (('Director' in ln or 'Regional Director' in ln) and ('Pipeline Safety' in ln or 'Pipeline and Hazardous Materials Safety Administration' in ln)):
            name=lines[i-1] if i>0 else None
            return name, ln
    return None, None


def parse_viol(text):
    m=re.search(r'\\bProposed (?:Civil Penalty|Compliance Order)\\b', text)
    body=text[:m.start()] if m else text
    nums=[]
    for line in body.splitlines():
        mm=re.match(r'"'^'"\\s*(\\d+)\\.\\s*"'$'"', line)
        if mm:
            n=int(mm.group(1))
            if n not in nums:
                nums.append(n)
        else:
            mm=re.match(r'"'^'"\\s*(\\d+)\\.\\s', line)
            if mm:
                n=int(mm.group(1))
                if n not in nums:
                    nums.append(n)
    secs=[]
    for line in body.splitlines():
        s=line.strip()
        m1=re.match(r'"'^§'"\\s*([0-9]{3})\\.([0-9]+)', s)
        if m1:
            sec=f'§ {m1.group(1)}.{m1.group(2)}'
            if sec not in secs:
                secs.append(sec)
    return len(nums), secs

def parse_pco(text):
    m=re.search(r'PROPOSED COMPLIANCE ORDER', text)
    if not m:
        return 0, [], None
    sec=text[m.end():]
    letters=[]
    for line in sec.splitlines():
        mm=re.match(r'"'^'"\\s*([A-Z])\\.\\s*"'$'"', line)
        if mm and mm.group(1) not in letters:
            letters.append(mm.group(1))
        else:
            mm=re.match(r'"'^'"\\s*([A-Z])\\.\\s', line)
            if mm and mm.group(1) not in letters:
                letters.append(mm.group(1))
    durs=[]
    for m3 in re.finditer(r'within\\s+((?:one|\\d+)(?:\\s+year(?:s)?|\\s+month(?:s)?|\\s+day(?:s)?)?)', sec, re.I):
        expr=m3.group(1).lower().strip()
        if expr.startswith('one '):
            num=1; unit=expr.split()[1]
        else:
            num=int(expr.split()[0]); unit=expr.split()[1]
        if 'day' in unit:
            durs.append(num)
        elif 'month' in unit:
            durs.append(num*30)
        elif 'year' in unit:
            durs.append(num*365)
    return len(letters), letters, max(durs) if durs else None

bad=[]
part_counter=Counter()
for d in data['documents']:
    text=open(d['doc_path'],encoding='utf-8',errors='ignore').read()
    cpf, issue, op = parse_date_and_cpf(text)
    dr, states_found, opening = parse_opening(text)
    nviol, secs = parse_viol(text)
    npco, letters, longest = parse_pco(text)
    name, title = parse_signer(text)
    if not op or not cpf or not issue or not name or not title:
        bad.append((d['doc_name'], op, cpf, issue, name, title))
    if not states_found:
        part_counter['no_state'] += 1
    if npco==0:
        part_counter['no_pco'] += 1
    if nviol==0:
        part_counter['no_viol'] += 1
print('bad count', len(bad))
print('sample bad', bad[:5])
print('no_state', part_counter['no_state'], 'no_pco', part_counter['no_pco'], 'no_viol', part_counter['no_viol'])
