                starts.append((m.start(), n))
    starts=sorted(set(starts))
    blocks=[]
    for idx,(pos,num) in enumerate(starts):
        end=starts[idx+1][0] if idx+1 < len(starts) else len(body)
        blocks.append((num, body[pos:end]))
