    ones={'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10,'eleven':11,'twelve':12,'thirteen':13,'fourteen':14,'fifteen':15,'sixteen':16,'seventeen':17,'eighteen':18,'nineteen':19}
    tens={'twenty':20,'thirty':30,'forty':40,'fifty':50,'sixty':60,'seventy':70,'eighty':80,'ninety':90}
    total=0
    current=0
    for tok in expr.split():
        if tok in ones:
            current += ones[tok]
        elif tok in tens:
            current += tens[tok]
        elif tok == 'hundred':
            current = max(1,current) * 100
        elif tok.isdigit():
            current += int(tok)
    total += current
    return total if total else None

def q11_longest_deadline(text, hdr):
    idx=text.rfind('PROPOSED COMPLIANCE ORDER')
    if idx==-1:
        idx=text.rfind('Proposed Compliance Order')
    if idx==-1: return 'NOT_FOUND'
    sec=text[idx:].replace('\\n',' ')
    durs=[]
    for m in re.finditer(r'within\\s+([A-Za-z\\s\\(\\)\\-]+?)\\s*(day(?:s)?|month(?:s)?|year(?:s)?)\\b', sec, re.I):
        span=sec[max(0,m.start()-40):m.end()+40].lower()
        if any(w in span for w in ['progress','update','quarterly']):
            continue
        num=words_to_num(m.group(1))
        if num is None:
            continue
        unit=m.group(2).lower()
        days=num if 'day' in unit else num*30 if 'month' in unit else num*365
        durs.append(days)
    return str(max(durs)) if durs else 'NOT_FOUND'
def q12_signer(text, hdr): return f\"{hdr['signer_name']}, {hdr['signer_title']}\" if hdr and hdr['signer_name'] and hdr['signer_title'] else 'NOT_FOUND'

